#[%dw 2.0
output json indent=false

---
{
 step: "After Retrieved Weathers",
 data: {
  business: {
  	weathers: sizeOf(payload)
  },
  technical: {}
 }
}]

set-payload.value:
#[%dw 2.0
output application/json  


var weatherMapping = readUrl("classpath://WeatherCode.csv", "application/csv")

fun weatherFunction(code) =
    (weatherMapping filter ($.source1 as Number == code))[0].target default "Inconnu"

var weathers = [payload]
---
weathers map (location) -> {
  coordinates: {
    latitude: location.latitude,
    longitude: location.longitude
  },
  forecast: location.daily.time map ((date, index) -> {
    date: date,
    temperature: {
      min: (location.daily.temperature_2m_min[index] ++ "°C") as String default "Non disponible",
      max: (location.daily.temperature_2m_max[index] ++ "°C") as String default "Non disponible"
    },
    weather: weatherFunction(location.daily.weather_code[index])
  })
}]

logger.message:
#[%dw 2.0
output json indent=false

---
{
 step: vars.metadata.endStep,
 data: {
